"use client";

import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Calendar, type CalendarProps } from "@/components/ui/calendar";
import {
  Popover,
  PopoverTrigger,
  PopoverContent,
} from "@/components/ui/popover";
import { Icon } from "@/components/ui/icon";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { useFlowPress } from "@/lib/sahajiv-motion/flow-press";
export const datePickerVariants = cva("v-menuhost [display:inline-block]");
export type DatePickerProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  date?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date | undefined) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placeholder?: string;
  disabled?: boolean;
  calendarProps?: Omit<CalendarProps, "selected" | "onSelect">;
  formatDate?: (date: Date) => string;
  triggerProps?: React.ComponentProps<"button">;
};
export function DatePicker(datePickerProps: DatePickerProps) {
  const {
    className,
    date,
    defaultDate,
    onDateChange,
    open,
    defaultOpen = false,
    onOpenChange,
    placeholder = "Pick a date",
    disabled,
    calendarProps,
    formatDate = (date) =>
      date.toLocaleDateString(undefined, {
        day: "numeric",
        month: "short",
        year: "numeric",
      }),
    triggerProps,
    ...props
  } = datePickerProps;
  const [internalDate, setInternalDate] = React.useState(defaultDate);
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const value = Object.prototype.hasOwnProperty.call(datePickerProps, "date")
    ? date
    : internalDate;
  const setOpen = (next: boolean) => {
    setInternalOpen(next);
    onOpenChange?.(next);
  };
  return (
    <Popover open={open ?? internalOpen} onOpenChange={setOpen}>
      <div
        data-slot="date-picker"
        data-part="root"
        data-datepicker=""
        className={cn(datePickerVariants(), className)}
        {...props}
      >
        <DatePickerTrigger disabled={disabled} {...triggerProps}>
          <Icon name="calendar" />
          <span data-value="">{value ? formatDate(value) : placeholder}</span>
          <Icon name="chevron-down" />
        </DatePickerTrigger>
        <DatePickerContent>
          <Calendar
            autoFocus
            defaultMonth={value}
            {...calendarProps}
            selected={value}
            onSelect={(next) => {
              setInternalDate(next);
              onDateChange?.(next);
              setOpen(false);
            }}
          />
        </DatePickerContent>
      </div>
    </Popover>
  );
}
export type DatePickerTriggerProps = React.ComponentProps<
  typeof PopoverTrigger
>;
export function DatePickerTrigger({
  className,
  ref,
  ...props
}: DatePickerTriggerProps) {
  const morphRef = useMorph<HTMLButtonElement>("buttons", ref);
  const pressRef = useFlowPress(morphRef);
  return (
    <PopoverTrigger
      ref={pressRef}
      data-slot="date-picker-trigger"
      data-part="trigger"
      className={cn("v-select -ink", className)}
      {...props}
    />
  );
}
export type DatePickerContentProps = React.ComponentProps<
  typeof PopoverContent
>;
export function DatePickerContent({
  className,
  ...props
}: DatePickerContentProps) {
  return (
    <PopoverContent
      data-slot="date-picker-content"
      data-part="content"
      align="start"
      sideOffset={8}
      className={className}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  )[data-morph] {
  --mfill: var(--v-beige);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-ink[data-morph] {
  --mfill: var(--v-ink);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]) {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  height: var(--ctl-md);
  padding: 0 var(--s-4) 0 var(--s-5);
  border-radius: var(--r-pill);
  background: var(--v-beige);
  font-size: var(--fs-control);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-ink {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block {
  width: 100%;
  height: var(--ctl-lg);
  font-size: var(--fs-body);
  font-weight: 400;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-sm {
  height: var(--ctl-sm);
  font-size: 13px;
  padding: 0 12px 0 14px;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"])
  .v-icon {
  width: 14px;
  height: 14px;
  stroke-width: 2.4;
}
.v-popover:where([data-slot="date-picker"], [data-slot^="date-picker-"]) {
  background: var(--popover);
  border-radius: var(--r-card);
  padding: var(--s-5);
  box-shadow: var(--shadow-float);
  border: 1px solid var(--v-border);
}
.v-menuhost:where([data-slot="date-picker"], [data-slot^="date-picker-"])
  > .v-menu {
  z-index: var(--z-dialog);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]):not(
    .-ink
  ) {
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
:root[data-mode="dark"]
  .v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]):not(
    .-ink
  ) {
  color: var(--v-text);
}
:root[data-mode="dark"]
  .v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-ink {
  background: var(--v-pink);
  color: var(--v-on-accent);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ):disabled {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  opacity: 1;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]) {
  height: 40px;
  padding: 0 12px 0 16px;
  gap: 10px;
  box-shadow: inset 0 0 0 1px var(--v-edge);
  background: var(--v-canvas);
  color: var(--v-text);
  font-weight: 500;
  transition:
    background var(--t-micro),
    box-shadow var(--t-micro);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]):hover {
  background: var(--v-beige);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  )[aria-expanded="true"] {
  box-shadow: inset 0 0 0 2px var(--v-brand);
  background: var(--v-pink-soft);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"])
  > .v-icon:last-child {
  width: 14px;
  height: 14px;
  stroke-width: 2.4;
  color: var(--v-text-2);
  transition: transform var(--t-element) var(--enter);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  )[aria-expanded="true"]
  > .v-icon:last-child {
  transform: rotate(180deg);
  color: var(--v-text);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-ink {
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: none;
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-ink:hover {
  background: var(--v-ink-soft);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-ink
  > .v-icon:last-child {
  color: rgba(251, 244, 230, 0.7);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-ink[aria-expanded="true"] {
  background: var(--v-ink);
  box-shadow: inset 0 0 0 2px var(--v-pink);
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-ink[aria-expanded="true"]
  > .v-icon:last-child {
  color: var(--v-pink);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block {
  width: 100%;
  height: 52px;
  padding: 0 8px 0 8px;
  font-size: var(--fs-body);
  font-weight: 500;
  background: var(--input);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  > span:first-child {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  > span:first-child
  > [data-value],
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  > span:first-child
  > span:not(.v-disk) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  .v-disk {
  width: 36px;
  height: 36px;
  flex: none;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  .v-disk
  .v-icon {
  width: 17px;
  height: 17px;
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  > .v-icon:last-child {
  width: 28px;
  height: 28px;
  padding: 7px;
  border-radius: 50%;
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1px var(--v-border);
  color: var(--v-text);
  stroke-width: 2.2;
  flex: none;
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-block[aria-expanded="true"]
  > .v-icon:last-child {
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: none;
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-block:hover {
  background: color-mix(in oklab, var(--input) 90%, var(--v-canvas));
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ).-block[aria-expanded="true"] {
  background: var(--v-pink-soft);
}
.v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-sm {
  height: 32px;
  padding: 0 10px 0 14px;
  font-size: 13px;
}
.v-select:where(
    [data-slot="date-picker"],
    [data-slot^="date-picker-"]
  ):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
:root[data-mode="dark"]
  .v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]):not(
    .-ink
  ) {
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
:root[data-mode="dark"]
  .v-select:where([data-slot="date-picker"], [data-slot^="date-picker-"]).-block
  > .v-icon:last-child {
  background: var(--v-beige-2);
  box-shadow: none;
  color: var(--v-text);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="date-picker"],
  [data-slot^="date-picker-"],
  [data-slot="date-picker"]::before,
  [data-slot="date-picker"]::after,
  [data-slot^="date-picker-"]::before,
  [data-slot^="date-picker-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}


}
